/* ---------- widget: solution mixer ---------- */
function onTheory(root){const w=root.querySelector('#w-mix');if(!w)return;
  w.innerHTML=`<label>Раствор 1: m₁ = <output id="o1">100</output> г<input type="range" id="m1" min="0" max="300" step="10" value="100"></label>
<label>w₁ = <output id="o2">10</output> %<input type="range" id="w1" min="0" max="60" step="1" value="10"></label>
<label>Раствор 2: m₂ = <output id="o3">300</output> г<input type="range" id="m2" min="0" max="300" step="10" value="300"></label>
<label>w₂ = <output id="o4">30</output> %<input type="range" id="w2" min="0" max="60" step="1" value="30"></label>
<label>Долить воды: <output id="o5">0</output> г<input type="range" id="mw" min="0" max="300" step="10" value="0"></label>
<div id="wS" style="display:flex;justify-content:center"></div><div id="wO" class="small" style="text-align:center;margin-top:6px"></div>`;
  const q=id=>w.querySelector(id);
  const draw=()=>{const m1=+q('#m1').value,w1=+q('#w1').value,m2=+q('#m2').value,w2=+q('#w2').value,mw=+q('#mw').value;
    q('#o1').textContent=m1;q('#o2').textContent=w1;q('#o3').textContent=m2;q('#o4').textContent=w2;q('#o5').textContent=mw;
    const ms=m1*w1/100+m2*w2/100,M=m1+m2+mw;const wr=M?ms/M*100:0;const mx=Math.max(300,M/2.2);
    let s=beaker(8,26,56,64,m1/300,w1/60,N(w1)+' %',m1+' г')+T(76,62,'+',{fs:20})+beaker(88,26,56,64,m2/300,w2/60,N(w2)+' %',m2+' г')+T(156,62,'+',{fs:20})+beaker(168,26,46,64,mw/300,0,'вода',mw+' г')+T(228,62,'=',{fs:20});
    s+=beaker(242,18,72,72,Math.min(1,M/900),wr/60,M?N(rd(wr,1))+' %':'—',M+' г');
    q('#wS').innerHTML=SV(320,112,s,'Смешивание растворов');
    q('#wO').innerHTML=M?`m(в-ва) = ${N(rd(m1*w1/100,1))} + ${N(rd(m2*w2/100,1))} = ${N(rd(ms,1))} г; m(р-ра) = ${m1} + ${m2} + ${mw} = ${M} г; w = ${N(rd(ms,1))} / ${M} ≈ <span class="out">${N(rd(wr,1))} %</span>`:'Налей что-нибудь 🙂';};
  w.querySelectorAll('input').forEach(i=>i.oninput=draw);draw();}

