RULE(0,'Что такое <b>раствор</b>?','Однородная смесь растворителя и растворённого вещества',['Любая смесь веществ, например песок в воде','Чистое вещество, растворённое в себе','Смесь, в которой частицы видны невооружённым глазом'],
{short:'Раствор однороден: растворённое вещество равномерно распределено в растворителе.',explain:'Раствор — <b>однородная</b> смесь растворителя и растворённого вещества (и продуктов их взаимодействия). Песок в воде — неоднородная смесь (взвесь): песчинки видны и оседают. В растворе частицы вещества размером с молекулы, их не видно, и они не оседают.',
explain2:'Проверка: налей и подожди. Солёная вода остаётся прозрачной и одинаковой сверху и снизу — это раствор. Песок оседает на дно — не раствор.'});
RULE(0,'Какой раствор называют <b>насыщенным</b>?','Раствор, в котором при данной температуре вещество больше не растворяется',['Раствор, в котором растворено очень много вещества','Раствор с массовой долей 100 %','Раствор, который нельзя разбавить'],
{short:'Насыщенный = «больше не лезет» при этой температуре.',explain:'Насыщенный раствор — тот, в котором при данной температуре вещество <b>больше не растворяется</b>: лишнее остаётся на дне. «Много вещества» — не определение: насыщенный раствор гипса содержит всего 0,2 % вещества, а ненасыщенный раствор сахара может быть 60 %-м.',
explain2:'Как губка: пока впитывает — ненасыщенная, перестала впитывать — насыщенная. Нагрел воду — «губка» стала больше (для большинства твёрдых веществ), и снова можно растворять.'});
G(0,()=>{const P=[['Как меняется растворимость газов в воде при <b>нагревании</b>?','уменьшается','Газы при нагревании растворяются хуже: молекулы газа быстрее движутся и «вылетают» из воды. Поэтому тёплая газировка быстрее выдыхается, а рыбам летом в тёплых прудах не хватает кислорода.'],
 ['Как меняется растворимость большинства <b>твёрдых</b> веществ при нагревании?','увеличивается','Частицы горячей воды быстрее разбирают кристалл. Например, s(KNO₃) при 20 °С — 31,6 г, а при 60 °С — 110 г на 100 г воды.'],
 ['Как меняется растворимость газов при <b>повышении давления</b>?','увеличивается','Давление «вдавливает» газ в жидкость. Поэтому газировку разливают под давлением, а при открытии давление падает — газ выходит пузырями.'],
 ['Как меняется растворимость NaCl при нагревании от 20 °С до 80 °С?','почти не меняется','По таблице: 35,9 г → 38,0 г на 100 г воды — рост очень маленький. Поэтому соль из морской воды получают выпариванием, а не охлаждением.']];
 const p=pick(P);return CH(p[0],p[1],['увеличивается','уменьшается','почти не меняется','становится равной нулю'].filter(x=>x!==p[1]).slice(0,3),{short:p[2],explain:`Ответ: <b>${p[1]}</b>. ${p[2]}`,explain2:'Запомни пару: «твёрдые — горячее лучше», «газы — холоднее и под давлением лучше». NaCl — исключение-«ленивец»: его растворимость почти не зависит от температуры.'});});
G(0,()=>{const sub=pick([['NaCl','поваренной соли',NACL],['KNO3','нитрата калия',KNO3]]);const t=pick([20,40,60]);const s=sub[2][t];const mw=pick([50,100,200,250]);const max=s*mw/100;
 const k=pick([0.5,0.8,1,1.3]);const ms=rd(max*k,0)||1;const st=ms<max-1e-9?0:(Math.abs(ms-max)<0.5?1:2);if(st===1&&ms!==max)return null;
 const opts=['ненасыщенный','насыщенный, всё растворилось','насыщенный, часть вещества осталась на дне'];const ans=ms<max?0:ms===max?1:2;
 return {type:'choice',q:`Растворимость ${sub[1]} при ${t} °С — ${N(s)} г на 100 г воды. В ${mw} г воды при ${t} °С насыпали ${N(ms)} г ${sub[1]} и перемешали. Какой получился раствор?`,opts,ans,
 short:`В ${mw} г воды растворится максимум ${N(rd(max,2))} г.`,
 explain:`Сначала считаем, сколько вещества <b>может</b> раствориться в ${mw} г воды: ${N(s)} · ${mw}/100 = ${N(rd(max,2))} г. Насыпали ${N(ms)} г — ${ms<max?'меньше предела → раствор <b>ненасыщенный</b>, можно растворить ещё '+N(rd(max-ms,2))+' г.':ms===max?'ровно столько → раствор <b>насыщенный</b>.':'больше предела → растворится только '+N(rd(max,2))+' г, раствор <b>насыщенный</b>, а '+N(rd(ms-max,2))+' г останется на дне.'}`,
 explain2:`Растворимость дана «на 100 г воды». У нас ${mw} г воды — это ${N(mw/100)} таких «порций», в каждую влезает ${N(s)} г. Всего влезет ${N(rd(max,2))} г.`};});

